package com.termux.app.workspace;
import android.app.Application;import android.content.res.Configuration;import android.os.Looper;import android.view.*;import android.widget.*;import android.graphics.drawable.*;import com.termux.R;import com.termux.app.TermuxActivity;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import java.util.*;import java.util.concurrent.atomic.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class AgentProjectPanelCompactLayoutTest {
 TermuxActivity activity;AgentProjectPanel panel;boolean valid=true,available=true;String opened="",jumped="",location="";AtomicInteger reads=new AtomicInteger(),refreshes=new AtomicInteger();List<JSONObject> rows=new ArrayList<>();
 void idle()throws Exception{for(int n=0;n<20;n++){Shadows.shadowOf(Looper.getMainLooper()).idle();Thread.sleep(5);}}
 void measure(View root){root.measure(View.MeasureSpec.makeMeasureSpec(320,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(600,View.MeasureSpec.EXACTLY));root.layout(0,0,320,600);}
 void tap(LinearLayout row,View target)throws Exception{assertTrue("Action attached to visible fixture window",target.isShown());long t=android.os.SystemClock.uptimeMillis();float x=target.getLeft()+target.getWidth()/2f,y=target.getTop()+target.getHeight()/2f;for(int action:new int[]{MotionEvent.ACTION_DOWN,MotionEvent.ACTION_UP}){MotionEvent e=MotionEvent.obtain(t,t+(action==MotionEvent.ACTION_UP?25:0),action,x,y,0);try{assertTrue(row.dispatchTouchEvent(e));}finally{e.recycle();}}Shadows.shadowOf(Looper.getMainLooper()).idleFor(java.time.Duration.ofMillis(250));idle();}


 JSONObject file(String key)throws Exception{return new JSONObject().put("key",key).put("message",key).put("kind","attachment").put("attachment",new JSONObject().put("id","0123456789abcdef0123456789abcdef").put("path","/fake/"+key+".zip").put("name",key+".zip").put("bytes",42));}
 void check(String agent)throws Exception{for(int theme:new int[]{R.style.Theme_Termux,R.style.Theme_Termux_Black})for(String lang:new String[]{"ru","en"})for(float scale:new float[]{1f,2f}){
  valid=true;available=true;opened=jumped=location="";reads.set(0);refreshes.set(0);rows.clear();rows.add(file("first"));rows.add(file("second"));activity=Robolectric.buildActivity(TermuxActivity.class).get();activity.setTheme(theme);WorkspaceLanguage.select(activity,lang);WorkspaceLanguage.apply(activity);Configuration before=new Configuration(activity.getResources().getConfiguration());Configuration large=new Configuration(before);large.fontScale=scale;activity.getResources().updateConfiguration(large,activity.getResources().getDisplayMetrics());activity.getResources().getDisplayMetrics().scaledDensity=activity.getResources().getDisplayMetrics().density*scale;
  WorkspaceStore.Session profile=new WorkspaceStore.Session();profile.environment=agent.equals("codex")?"codex":"ubuntu";profile.claudeAgent=agent.equals("claude");profile.geminiAgent=agent.equals("gemini");profile.aiAgent=agent.equals("opencode")?"opencode":"";
  AgentProjectPanel.Chat source=new AgentProjectPanel.Chat(){public boolean valid(){return valid;}public List<JSONObject> rows(){return rows;}public boolean hasOlder(){return false;}public void older(){fail("Layout must not load history");}public void refresh(){refreshes.incrementAndGet();}public void open(JSONObject file){opened=file.optString("path");}public boolean jump(String key){jumped=key;return true;}public void observe(Runnable changed){}public void close(){valid=false;}};
  AgentProjectPanel.Backend backend=new AgentProjectPanel.Backend(){public byte[] read(String script,int max){reads.incrementAndGet();return script.contains("rev-parse")?"NO_PROJECT\0".getBytes():(available?"AVAILABLE 42":"MISSING").getBytes();}public void close(){}};
  panel=new AgentProjectPanel(activity,profile,"/fake",source,backend);LinearLayout files=new LinearLayout(activity);View root=panel.wrap(files,v->{},path->location=path);android.app.Dialog window=new android.app.Dialog(activity);window.setContentView(root);window.show();
  try{panel.select(1);idle();measure(root);ViewGroup page=(ViewGroup)panel.content.getChildAt(1);assertEquals(2,page.getChildCount());LinearLayout toolbar=(LinearLayout)page.getChildAt(0);assertEquals(LinearLayout.HORIZONTAL,toolbar.getOrientation());assertSame(panel.attachmentSearch,toolbar.getChildAt(1));View box=toolbar.getChildAt(0);assertTrue(panel.attachmentRefresh instanceof WorkspaceIconButton);assertEquals(WorkspaceDialogs.dp(activity,44),box.getMeasuredWidth());assertEquals(WorkspaceDialogs.dp(activity,44),box.getMeasuredHeight());assertEquals(box.getRight()+WorkspaceDialogs.dp(activity,8),panel.attachmentSearch.getLeft());assertEquals(toolbar.getWidth()-panel.attachmentSearch.getLeft(),panel.attachmentSearch.getWidth());assertEquals(lang.equals("ru")?"Обновить":"Refresh",panel.attachmentRefresh.getContentDescription());assertEquals("",panel.attachmentRefresh.getText().toString());assertNull(root.findViewWithTag("project-attachments-search-clear"));assertEquals(page.getHeight()-toolbar.getHeight(),page.getChildAt(1).getHeight());
   LinearLayout entry=root.findViewWithTag("project-attachment-first"),info=root.findViewWithTag("project-attachment-information-first"),strip=root.findViewWithTag("project-attachment-actions-first");assertSame(entry,info.getParent());assertSame(entry,strip.getParent());assertTrue("Strip below its information card",strip.getTop()>=info.getBottom());assertEquals(LinearLayout.HORIZONTAL,strip.getOrientation());assertEquals(3,strip.getChildCount());boolean wrapped=false;for(int n=0;n<3;n++){TextView b=(TextView)strip.getChildAt(n);assertTrue(b.getWidth()>=WorkspaceDialogs.dp(activity,44));assertTrue(b.getHeight()>=WorkspaceDialogs.dp(activity,44));assertNull(b.getEllipsize());assertTrue(b.isClickable());assertTrue(b.isFocusable());assertEquals(strip.getHeight()-strip.getPaddingTop()-strip.getPaddingBottom(),b.getHeight());StateListDrawable state=(StateListDrawable)b.getBackground();GradientDrawable normal=(GradientDrawable)Shadows.shadowOf(state).getDrawableForState(new int[]{});GradientDrawable pressed=(GradientDrawable)Shadows.shadowOf(state).getDrawableForState(new int[]{android.R.attr.state_pressed});assertEquals(WorkspaceDialogs.dp(activity,1),Shadows.shadowOf(normal).getStrokeWidth());assertEquals(0xff393a3c,Shadows.shadowOf(normal).getStrokeColor());assertNotSame(normal,pressed);if(n>0)assertNotSame(b.getBackground(),strip.getChildAt(n-1).getBackground());assertNotNull(b.getLayout());assertTrue("All wrapped lines fit",b.getLayout().getHeight()+b.getTotalPaddingTop()+b.getTotalPaddingBottom()<=b.getHeight());wrapped|=b.getLineCount()>1;}
   if(scale==2f){TextView multiple=(TextView)strip.getChildAt(1);multiple.setText(lang.equals("ru")?"К\nсообщению":"Go to\nmessage");measure(root);assertEquals(2,multiple.getLineCount());assertTrue("Explicit multiline action fits its intrinsic strip",multiple.getLayout().getHeight()+multiple.getTotalPaddingTop()+multiple.getTotalPaddingBottom()<=multiple.getHeight());}info.performClick();assertEquals("/fake/first.zip",opened);assertEquals("",jumped);assertEquals("",location);tap(strip,strip.getChildAt(0));assertEquals("first",jumped);assertEquals("",location);tap(strip,strip.getChildAt(2));assertEquals("/fake",location);assertEquals(0,panel.selected);panel.select(1);idle();measure(root);LinearLayout second=root.findViewWithTag("project-attachment-actions-second");root.findViewWithTag("project-attachment-information-second").performClick();assertEquals("/fake/second.zip",opened);int beforeReads=reads.get();measure(root);assertEquals(beforeReads,reads.get());
   available=false;panel.availabilityCache.clear();panel.renderAttachments();idle();measure(root);strip=root.findViewWithTag("project-attachment-actions-first");assertEquals(View.VISIBLE,strip.getChildAt(0).getVisibility());assertEquals(View.VISIBLE,strip.getChildAt(1).getVisibility());assertEquals(View.VISIBLE,strip.getChildAt(2).getVisibility());panel.select(2);idle();measure(root);page=(ViewGroup)panel.content.getChildAt(2);assertEquals(2,page.getChildCount());assertSame(panel.gitSearch.getParent(),page.getChildAt(0));assertNull(panel.changes.findViewWithTag("project-attachment-actions-first"));assertNull(root.findViewWithTag("project-changes-search-clear"));assertSame(files,panel.content.getChildAt(0));assertEquals(0,files.getChildCount());assertEquals(0,refreshes.get());
  }finally{window.dismiss();Shadows.shadowOf(Looper.getMainLooper()).idle();panel.close();panel=null;activity.getResources().updateConfiguration(before,activity.getResources().getDisplayMetrics());activity.getResources().getDisplayMetrics().scaledDensity=activity.getResources().getDisplayMetrics().density*before.fontScale;activity.finish();activity=null;}
 }}
 @After public void close(){if(panel!=null)panel.close();if(activity!=null)activity.finish();}
 @Test public void codexCompactToolbarAndPerCardActions()throws Exception{check("codex");}
 @Test public void claudeCompactToolbarAndPerCardActions()throws Exception{check("claude");}
 @Test public void geminiCompactToolbarAndPerCardActions()throws Exception{check("gemini");}
 @Test public void openCodeCompactToolbarAndPerCardActions()throws Exception{check("opencode");}
}
